function validatePrompt(prompt, policy) {
  // normalize
  let p = prompt.trim();
  // redaction rules (pseudo)
  policy.redactionPatterns.forEach(r => p = p.replace(r, 'REDACTED'));
  // injection guard (very simple placeholder)
  const blocked = policy.injectionPatterns.some(pat => new RegExp(pat, 'i').test(p));
  return { valid: !blocked, redacted: p };
}
```

